#!/usr/bin/env python3
# Flugfunk ersetzt Pinneberg. Kein Mesh. Hoeren nur im LAN.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
DATEIEN = ("dashboard.py", "prepper_sdr.py", "pushover_push.py", "pinneberg_rx.py")
PAKETE = """===== SCHRITT PAKETE, dieses Skript installiert nichts =====
sudo apt-get install -y rtl-airband
# whisper.cpp selbst bauen, Binary nach /home/fmg/prepper-dashboard/bin/whisper-cli
# Modell ggml-base.en.bin nach /home/fmg/prepper-dashboard/models/ggml-base.en.bin
# ADS-B: readsb oder dump1090 aircraft.json wird automatisch gesucht.
# Anderer Pfad: eine Zeile in /home/fmg/prepper-dashboard/flugfunk_adsb.path
===== ENDE SCHRITT PAKETE ====="""
TITEL = "Stick 3 · Pinneberg".encode()

def load():
    return PAYLOAD_JSON

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin Minute %02d" % jetzt.minute

def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0 or old in neu:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-flugfunk-*"))
    bak = path.with_name(path.name + ".bak-flugfunk-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path: Path, data: bytes):
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-flugfunk")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def rolle_bytes():
    return json.dumps({
        "bias_tee": False, "gain": 40, "rolle": "flugfunk",
        "serial": "26102403", "spyverter": False,
    }, sort_keys=True).encode("ascii")

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    print(PAKETE)
    roh = load()
    paare = {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in roh["pairs"][name]] for name in DATEIEN}
    flug_neu = base64.b64decode(roh["flugfunk"])
    if sha(flug_neu) != roh["sha"]:
        print("STOP: Nutzlast beschaedigt")
        return 2
    blobs = {}
    for name in DATEIEN:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
    flug_pfad = ordner / "flugfunk.py"
    flug_alt = flug_pfad.read_bytes() if flug_pfad.is_file() and not flug_pfad.is_symlink() else None
    if flug_alt is not None:
        print("flugfunk.py sha16 %s bytes %d" % (sha(flug_alt)[:16], len(flug_alt)))
    try:
        ziel = {name: verwandle(blobs[name], paare[name]) for name in DATEIEN}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    ziel["flugfunk.py"] = flug_neu
    for name, data in list(ziel.items()):
        compile(data, name, "exec")
    if b"flugfunkBox" not in ziel["dashboard.py"] or TITEL in ziel["dashboard.py"]:
        print("STOP: Kachel fehlt")
        return 2
    if b"SESS.starten" not in ziel["prepper_sdr.py"] or b"_pnrx.SESS.start" in ziel["prepper_sdr.py"]:
        print("STOP: Stick-Sperre fehlt")
        return 2
    if b'startswith("flugfunk")' not in ziel["pushover_push.py"]:
        print("STOP: Notfall-Pushover fehlt")
        return 2
    if b"flugfunk_rolle.json" not in ziel["pinneberg_rx.py"]:
        print("STOP: Pinneberg-Sperre fehlt")
        return 2
    print("flugfunk.py endstand sha16 %s bytes %d" % (sha(flug_neu)[:16], len(flug_neu)))
    for name in DATEIEN:
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    gleich = all(blobs[name] == ziel[name] for name in DATEIEN) and flug_alt == flug_neu
    frei, meldung = fenster(jetzt)
    print(meldung)
    if gleich:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/flugfunk")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        for name in DATEIEN:
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
        rolle = ordner / "pinneberg_rolle.py"
        if rolle.is_file() and not rolle.is_symlink():
            sichern(rolle, rolle.read_bytes())
        if flug_alt is not None:
            sichern(flug_pfad, flug_alt)
        schreiben(flug_pfad, flug_neu)
        schreiben(ordner / "flugfunk_rolle.json", rolle_bytes())
    except (OSError, RuntimeError):
        print("STOP beim Schreiben")
        return 3
    print("geschrieben. Pinneberg bleibt als Datei, startet nicht mehr.")
    if kein or ordner != DASH:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt aus.")
        return 2
    lauf = __import__("subprocess").run
    lauf(["systemctl", "restart", "prepper-sdr.service"], check=False)
    lauf(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Neu gestartet: prepper-sdr, prepper-dashboard.")
    return 0

def huelle(blob: bytes) -> bytes:
    try:
        compile(blob, "x", "exec")
        return blob
    except SyntaxError:
        geh = b"def _h():\n" + blob
        compile(geh, "x", "exec")
        return geh

def selftest() -> int:
    assert fenster(datetime(2026, 11, 21, 12, 5))[0]
    assert fenster(datetime(2026, 11, 21, 12, 39))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 4))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 40))[0]
    import tempfile
    roh = load()
    paare = {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in roh["pairs"][name]] for name in DATEIEN}
    ordner = Path(tempfile.mkdtemp(prefix="flugfunk-apply-"))
    for name in DATEIEN:
        (ordner / name).write_bytes(b"UNBERUEHRT")
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12)) == 2
    assert (ordner / "dashboard.py").read_bytes() == b"UNBERUEHRT"
    inhalt = {}
    for name, liste in paare.items():
        assert liste[0][0] not in liste[0][1]
        blob = huelle(liste[0][0])
        (ordner / name).write_bytes(blob)
        inhalt[name] = blob
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12)) == 0
    assert all((ordner / name).read_bytes() == inhalt[name] for name in DATEIEN)
    assert not (ordner / "flugfunk.py").exists()
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 4)) == 2
    assert all((ordner / name).read_bytes() == inhalt[name] for name in DATEIEN)
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12)) == 0
    assert (ordner / "flugfunk.py").is_file()
    assert sha((ordner / "flugfunk.py").read_bytes()) == roh["sha"]
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12)) == 0
    (ordner / "dashboard.py").write_bytes(b"ANDERES")
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12)) == 2
    assert (ordner / "dashboard.py").read_bytes() == b"ANDERES"
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

PAYLOAD_JSON = {"pairs": {"dashboard.py": [{"old": "", "new": ""}], "prepper_sdr.py": [{"old": "", "new": ""}], "pushover_push.py": [{"old": "", "new": ""}], "pinneberg_rx.py": [{"old": "ICAgICAgICAiIiJXYWVjaHRlcmZhZGVuLiBXYXJ0ZXQgYXVmIFN0aWNrIDMsIHN0YXJ0ZXQgbmV1LCBzYW1tZWx0IFpvbWJpZXMuIEtlaW4gSW5kZXgsIGtlaW4gendlaXRlciBTdGFydC4iIiIKICAgICAgICBpbXBvcnQgdGhyZWFkaW5nCg==", "new": ""}]}, "flugfunk": "", "sha": "49c5d016b06710c2037d7ea82acc7956d2096a5c7a8f640d72344fdca5c1cb3e"}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
